#!/usr/bin/env node
/**
 * Builds the single content manifest that drives the numbered feed.
 *
 * Sources of truth:
 *   content/projects.json  — hand written project entries
 *   content/photos.json    — hand written photo list
 *   blog/posts.json        — generated by scripts/sync-blog-posts.js
 *
 * Output:
 *   js/content.js          — assigns window.SITE_CONTENT = { items, counts }
 *
 * Keeping this as a .js file (rather than a fetched .json) means index.html
 * also works when opened straight from disk, with no server and no CORS.
 */
const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const read = file => JSON.parse(fs.readFileSync(path.join(ROOT, file), 'utf8'))

const projects = read('content/projects.json')
const photos = read('content/photos.json')

let posts = []
try {
  posts = read('blog/posts.json')
} catch (err) {
  console.warn('build-content: no blog/posts.json yet — run `npm run sync` first')
}

// Newest writing first, same rule the old blog.js used.
posts = [...posts].sort((a, b) => new Date(b.date) - new Date(a.date))

const items = [
  ...projects.map(p => ({ ...p })),
  ...posts.map(p => ({
    id: p.id,
    type: 'post',
    title: p.title,
    kicker: 'Writing',
    date: p.date,
    summary: p.excerpt || 'A note on building for the web.',
    body: p.body || '',
    tags: p.tags || [],
    href: p.url,
    linkLabel: 'Read the article',
  })),
  ...photos.map(p => ({ ...p })),
].map((item, i) => ({ ...item, number: i + 1 }))

const counts = {
  posts: items.length,
  projects: projects.length,
  writing: posts.length,
  photos: photos.length,
}

const banner = '/* Generated by scripts/build-content.js — do not edit by hand. */\n'
const body = `window.SITE_CONTENT = ${JSON.stringify({ items, counts }, null, 2)}\n`

fs.mkdirSync(path.join(ROOT, 'js'), { recursive: true })
fs.writeFileSync(path.join(ROOT, 'js/content.js'), banner + body)

console.log(
  `content: ${items.length} items — ${counts.projects} projects, ${counts.writing} posts, ${counts.photos} photos`,
)
